<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{t,duration}from'./i18n';import{videoFrames}from'./video-frames';import Icon from'./Icon.vue';import TrimTimeRange from'./TrimTimeRange.vue';
const props=defineProps<{files:File[];mode:'trim'|'merge';start:number;end:number}>(),emit=defineEmits<{start:[value:number];end:[value:number];valid:[value:boolean];move:[index:number,to:number];remove:[index:number]}>();
const player=ref<HTMLVideoElement>(),url=ref(''),length=ref(0),frames=ref<string[]>([]),clipFrames=ref<string[]>([]),clipDurations=ref<number[]>([]),selected=ref(0),previewError=ref(false),playingRange=ref(false);let abort:AbortController|undefined;let dragged=-1;
const timeFields=ref<InstanceType<typeof TrimTimeRange>>(),rangeValid=ref(false);
function clean(){abort?.abort();player.value?.pause();if(url.value)URL.revokeObjectURL(url.value);url.value='';rangeValid.value=false;emit('valid',false);}
function select(index:number){selected.value=index;player.value?.pause();if(url.value)URL.revokeObjectURL(url.value);url.value=props.files[index]?URL.createObjectURL(props.files[index]!):'';previewError.value=false;}
watch(()=>[props.files,props.mode]as const,async()=>{clean();length.value=0;frames.value=[];clipFrames.value=[];clipDurations.value=[];selected.value=0;select(0);abort=new AbortController();const signal=abort.signal;try{if(props.mode==='trim'&&props.files[0]){const result=await videoFrames(props.files[0],[.03,.2,.4,.6,.8,.97],signal);if(!signal.aborted){frames.value=result.images;if(!Number.isFinite(player.value?.duration)||!length.value){length.value=result.duration;emit('start',0);emit('end',result.duration);}}}else for(let index=0;index<props.files.length;index++){const result=await videoFrames(props.files[index]!,[.35],signal);if(signal.aborted)return;clipFrames.value[index]=result.images[0]!;clipDurations.value[index]=result.duration;}}catch{/* Native video reports unreadable sources separately. */}},{immediate:true});
function loaded(){const native=player.value?.duration;length.value=Number.isFinite(native)?native!:length.value;if(props.mode==='trim'&&Number.isFinite(length.value)&&length.value>0){emit('start',0);emit('end',length.value);}}
function setStart(value:number){value=Math.max(0,Math.min(value,props.end-.04));timeFields.value?.sync(value,props.end);emit('start',value);if(player.value)player.value.currentTime=value;}
function setEnd(value:number){value=Math.min(length.value,Math.max(value,props.start+.04));timeFields.value?.sync(props.start,value);emit('end',value);if(player.value)player.value.currentTime=Math.max(props.start,value-.04);}
function manualRange(start:number,end:number,edge:'start'|'end'){emit('start',start);emit('end',end);if(player.value)player.value.currentTime=edge==='start'?start:Math.max(start,end-.04);}
function validChanged(value:boolean){rangeValid.value=value;emit('valid',value);if(!value&&playingRange.value){player.value?.pause();playingRange.value=false;}}
async function preview(){if(!player.value)return;playingRange.value=true;player.value.currentTime=props.start;await player.value.play().catch(()=>{previewError.value=true;});}
function tick(){if(playingRange.value&&props.mode==='trim'&&player.value&&player.value.currentTime>=props.end){player.value.pause();playingRange.value=false;player.value.currentTime=props.start;}}
onBeforeUnmount(clean);
</script>
<template><section v-if="files.length" class="visual-editor" :aria-label="t(mode === 'trim' ? 'visualTrim' : 'visualMerge')"><div class="editor-screen"><video ref="player" :src="url" controls preload="metadata" playsinline :aria-label="t('preview')" @loadedmetadata="loaded" @error="previewError=true" @timeupdate="tick" /><span class="editor-file" dir="auto">{{ files[selected]?.name }}</span></div><p v-if="previewError" class="error" role="alert">{{ t('previewUnavailable') }}</p><template v-if="mode === 'trim' && length > 0"><div class="trim-toolbar"><TrimTimeRange ref="timeFields" :start="start" :end="end" :length="length" @change="manualRange" @valid="validChanged" /><button class="secondary" type="button" :disabled="!rangeValid" @click="preview"><Icon name="play" />{{ t('playSelection') }}</button></div><div class="trim-timeline" :style="{'--cut-start':`${start/length*100}%`,'--cut-end':`${end/length*100}%`}"><div class="timeline-frames"><img v-for="(image,index) in frames" :key="index" :src="image" alt=""></div><div class="trim-selection" aria-hidden="true"/><input class="trim-slider" type="range" min="0" :max="length" step="0.001" :value="start" :aria-label="t('cutInHandle')" @input="setStart(Number(($event.target as HTMLInputElement).value))"><input class="trim-slider end-handle" type="range" min="0" :max="length" step="0.001" :value="end" :aria-label="t('cutOutHandle')" @input="setEnd(Number(($event.target as HTMLInputElement).value))"></div><div class="timeline-times"><span>0:00</span><span>{{ duration(length/2) }}</span><span>{{ duration(length) }}</span></div><div class="mark-actions"><button type="button" class="text-button" @click="setStart(player?.currentTime??0)">{{ t('markStart') }}</button><button type="button" class="text-button" @click="setEnd(player?.currentTime??length)">{{ t('markEnd') }}</button></div></template><template v-if="mode === 'merge'"><p class="timeline-caption">{{ t('mergeVisualHint') }}</p><ol class="tool-files merge-clips"><li v-for="(file,index) in files" :key="index" :class="{selected:selected === index}" draggable="true" @dragstart="dragged=index" @dragover.prevent @drop.prevent="dragged >= 0 && emit('move',dragged,index)"><button class="clip-preview" type="button" :aria-label="t('preview') + ' · ' + file.name" @click="select(index)"><img v-if="clipFrames[index]" :src="clipFrames[index]" alt=""><Icon v-else name="movie" /><span>{{ index+1 }}</span></button><span dir="auto">{{ file.name }}</span><small>{{ duration(clipDurations[index]) }}</small><div><button v-if="index" class="icon-button" type="button" :aria-label="t('moveUp')" @click="emit('move',index,index-1)"><Icon name="up" /></button><button v-if="index < files.length-1" class="icon-button" type="button" :aria-label="t('moveDown')" @click="emit('move',index,index+1)"><Icon name="down" /></button><button class="icon-button" type="button" :aria-label="t('remove')" @click="emit('remove',index)"><Icon name="close" /></button></div></li></ol><p v-if="clipDurations.length">{{ t('totalDuration') }} · {{ duration(clipDurations.reduce((sum,n)=>sum+(n||0),0)) }}</p></template></section></template>
